  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.',
  'Use Contact Us' => 'Use Contact Us',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.',
  'Use the contact form' => 'Use the contact form',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.',
  'Video categories' => 'Video categories',
  'Video for everyone. Built for creators and viewers.' => 'Video for everyone. Built for creators and viewers.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Video upload, scheduling, thumbnails, and processing issues.',
  'Videos, thumbnails, captions, processing.' => 'Videos, thumbnails, captions, processing.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.',
